1	import type { Env } from '../env';
2	import type { CursorValue } from '../lib/cursor';
3	
4	export type DocMeta = {
5	  id: string;
6	  title: string;
7	  path: string;
8	  folderId: string;
9	  r2Key: string;
10	  updatedAt: string;
11	};
12	
13	export type ListDocsOpts = {
14	  workspaceId?: string;
15	  folderId?: string;
16	  tagId?: string;
17	  limit?: number;
18	  cursor?: CursorValue | null;
19	};
20	
21	export async function listDocs(env: Env, opts?: ListDocsOpts): Promise<DocMeta[]> {
22	  const folderId = opts?.folderId;
23	  const tagId = opts?.tagId;
24	  const limit = Math.min(Math.max(opts?.limit ?? 50, 1), 200);
25	  const cursor = opts?.cursor;
26	
27	  const where: string[] = [];
28	  const binds: unknown[] = [];
29	  const useJoin = Boolean(tagId);
30	
31	  const col = (name: string) => (useJoin ? `d.${name}` : name);
32	
33	  // Workspace scoping. A literal '*' is honoured as "no scoping" for an
34	  // admin tool; no existing caller passes it.
35	  if (opts?.workspaceId && opts.workspaceId !== '*') {
36	    where.push(`${col('workspace_id')} = ?`);
37	    binds.push(opts.workspaceId);
38	  }
39	
40	  where.push(`${col('status')}='active'`);
41	
42	  if (folderId) {
43	    where.push(`${col('folder_id')} = ?`);
44	    binds.push(folderId);
45	  }
46	  if (tagId) {
47	    where.push('dt.tag_id = ?');
48	    binds.push(tagId);
49	  }
50	  if (cursor) {
51	    where.push(`(${col('updated_at')} < ? OR (${col('updated_at')} = ? AND ${col('id')} < ?))`);
52	    binds.push(cursor.t, cursor.t, cursor.id);
53	  }
54	
55	  const select = useJoin
56	    ? `SELECT d.id, d.title, d.path, d.folder_id as folderId, d.r2_key as r2Key, d.updated_at as updatedAt
57	       FROM docs d
58	       JOIN doc_tags dt ON dt.doc_id = d.id`
59	    : `SELECT id, title, path, folder_id as folderId, r2_key as r2Key, updated_at as updatedAt
60	       FROM docs`;
61	
62	  const sql = `${select}
63	    WHERE ${where.join(' AND ')}
64	    ORDER BY ${col('updated_at')} DESC, ${col('id')} DESC
65	    LIMIT ${limit}`;
66	
67	  const res = await env.DB.prepare(sql).bind(...binds).all<DocMeta>();
68	  return res.results;
69	}
