71	export async function getDocByPath(env: Env, path: string, opts?: { workspaceId?: string }): Promise<DocMeta | null> {
72	  // docs has UNIQUE(workspace_id, path) — the same path can legitimately
73	  // exist in multiple workspaces. Without scoping, this returned the first
74	  // match and leaked content across workspaces. '*' bypasses for admin.
75	  const useScope = Boolean(opts?.workspaceId && opts.workspaceId !== '*');
76	  const where = useScope ? "status='active' AND path = ? AND workspace_id = ?" : "status='active' AND path = ?";
77	  const binds: unknown[] = useScope ? [path, opts!.workspaceId] : [path];
78	  const row = await env.DB.prepare(
79	    `SELECT id, title, path, folder_id as folderId, r2_key as r2Key, updated_at as updatedAt
80	     FROM docs
81	     WHERE ${where}
82	     LIMIT 1`
83	  )
84	    .bind(...binds)
85	    .first<DocMeta>();
86	  return row ?? null;
87	}
