2	import type { AppEnv } from '../env';
3	import { createNote, listNotes, getNote, type NoteType } from '../db/notes';
4	import { jsonError } from '../middleware/errors';
5	import { requireRole } from '../middleware/requireRole';
6	import { validateBody, isResponse } from '../middleware/validate';
7	import { z } from 'zod';
