10	const createNoteSchema = z.object({
11	  agentId: z.string().min(1, 'agentId is required').max(100),
12	  content: z.string().min(1, 'content is required').max(50000),
13	  type: z.enum(['daily', 'memo']),
14	  title: z.string().max(500).optional(),
15	});
16	
17	const VALID_TYPES = new Set<string>(['daily', 'memo']);
18	
19	// Cross-org notes registry. Mutation gate added in the same closure
20	// series as agents.ts (88efdb9) and the agent-* family (a32cba5).
21	export const notes = new Hono<AppEnv>()
22	  .get('/', async (c) => {
23	    const agentId = c.req.query('agentId') || c.req.query('agentName') || undefined;
24	    const type = c.req.query('type') || undefined;
25	    const since = c.req.query('since') || undefined;
26	    const limitRaw = c.req.query('limit');
27	    const limit = limitRaw ? Number(limitRaw) : undefined;
28	    const cursorRaw = c.req.query('cursor');
29	    const cursor = cursorRaw ? decodeCursor(cursorRaw) : undefined;
30	
31	    if (type && !VALID_TYPES.has(type)) {
32	      return jsonError(c, 400, 'VALIDATION_ERROR', 'Invalid type', { valid: ['daily', 'memo'] });
33	    }
34	
35	    const items = await listNotes(c.env, {
36	      agentId,
37	      type: type as NoteType | undefined,
38	      since,
39	      limit,
40	      cursor,
41	    });
42	    const effectiveLimit = Math.min(Math.max(limit ?? 50, 1), 200);
43	    const nextCursor = buildNextCursor(items, effectiveLimit, (n) => n.createdAt);
44	    return c.json({ items, nextCursor });
45	  })
46	  .get('/:id', async (c) => {
47	    const note = await getNote(c.env, c.req.param('id'));
48	    if (!note) return jsonError(c, 404, 'NOT_FOUND', 'Note not found');
49	    return c.json({ note });
50	  })
51	  .post('/', async (c) => {
52	    const denied = await requireRole(c, 'member');
53	    if (denied) return denied;
54	
55	    const data = await validateBody(c, createNoteSchema);
56	    if (isResponse(data)) return data;
57	
58	    const title = data.title || (data.type === 'daily'
59	      ? `${data.agentId} 日報 ${new Date().toISOString().slice(0, 10)}`
60	      : `${data.agentId} メモ`);
61	
62	    const id = await createNote(c.env, {
63	      agentId: data.agentId,
64	      type: data.type,
65	      title,
66	      content: data.content,
67	    });
68	
69	    const note = await getNote(c.env, id);
70	    return c.json({ note }, 201);
71	  });
