18	  title: string;
19	  content: string;
20	}): Promise<string> {
21	  const id = `act_${crypto.randomUUID()}`;
22	  const actionType = input.type === 'daily' ? 'daily_report' : 'memo';
23	
24	  await env.DB.prepare(
25	    `INSERT INTO agent_activity_log (id, agent_id, action_type, summary, details, ref_type, ref_id, metadata, created_at)
26	     VALUES (?, ?, ?, ?, ?, 'note', NULL, NULL, datetime('now'))`
27	  ).bind(
28	    id,
29	    input.agentId,
30	    actionType,
31	    input.title,
32	    input.content,
33	  ).run();
34	
35	  return id;
36	}
