38	export async function listNotes(env: Env, opts: {
39	  agentId?: string;
40	  type?: NoteType;
41	  since?: string;
42	  limit?: number;
43	  cursor?: CursorValue | null;
44	} = {}): Promise<Note[]> {
45	  const where: string[] = ["action_type IN ('daily_report', 'memo')"];
46	  const binds: unknown[] = [];
47	  const limit = Math.min(Math.max(opts.limit ?? 50, 1), 200);
48	
49	  if (opts.agentId) {
50	    where.push('agent_id = ?');
51	    binds.push(opts.agentId);
52	  }
53	  if (opts.type) {
54	    where.push('action_type = ?');
55	    binds.push(opts.type === 'daily' ? 'daily_report' : 'memo');
56	  }
57	  if (opts.since) {
58	    where.push('created_at >= ?');
59	    binds.push(opts.since);
60	  }
61	  if (opts.cursor) {
62	    where.push('(created_at < ? OR (created_at = ? AND id < ?))');
63	    binds.push(opts.cursor.t, opts.cursor.t, opts.cursor.id);
64	  }
65	
66	  const sql = `SELECT
67	    id,
68	    agent_id as agentId,
69	    action_type as actionType,
70	    summary as title,
71	    details as content,
72	    created_at as createdAt
73	  FROM agent_activity_log
74	  WHERE ${where.join(' AND ')}
75	  ORDER BY created_at DESC, id DESC
76	  LIMIT ${limit}`;
